#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import ast, sys, math, json
from collections import Counter

def Q(stem, opts, ans, ana, kn, mod, con):
    return {"stem":stem,"options":opts,"answer":ans,"analysis":ana,"knowledge":kn,"module":mod,"difficulty":"league","target":"both","concept":con}

def mk_ana(ABCD_parts, topic_full, common_mistakes, ans_letter):
    letters=['A','B','C','D']
    a=""
    for i in range(4):
        a += letters[i]+"选项："+ABCD_parts[i]+"。"
    a += "综上所述，"+topic_full+"的核心是结合定量计算与机制理解，需特别警惕常见误区："+common_mistakes+"。本题通过具体物种、具体监测数据的情境设计，考查联赛要求的\"数据处理+模型应用+逻辑推理\"综合能力。考生应建立从\"现象描述→机制分析→模型预测→保护/应用\"的完整思维链条，避免孤立记忆零散知识点，这样才能在多变的题型中灵活应对。"
    return a

# 读取现有
